import React from "react";
import {
  BrowserRouter,
  Routes,
  Route
} from "react-router-dom";

import Sidebar from "./components/Sidebar";
import Settings from "./pages/Settings";

function App() {
  return (
    <BrowserRouter>
      <div style={{
        display: "flex",
        background: "#0f172a",
        color: "white",
        minHeight: "100vh"
      }}>
        <Sidebar />

        <div style={{ flex: 1 }}>
          <Routes>
            <Route
              path="*"
              element={<Settings />}
            />
          </Routes>
        </div>
      </div>
    </BrowserRouter>
  );
}

export default App;
